INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6869293, 1034200, 28742, '<td valign="top">That comes from an incredibly short tree. ;-) Well done - one of my top picks.</td>', 'That comes from an incredibly short tree. ;-) Well done - one of my top picks.', '2012-09-25 18:19:59.000000', NULL, 1),
(6869295, 1033848, 28742, '<td valign="top">More light would be the difference between a 9 and a 10. :)</td>', 'More light would be the difference between a 9 and a 10. :)', '2012-09-25 18:20:35.000000', NULL, 1),
(6869296, 1034285, 28742, '<td valign="top">That''s prolly gonna hurt when you pull it out. ...can I do it?</td>', 'That''s prolly gonna hurt when you pull it out. ...can I do it?', '2012-09-25 18:20:50.000000', NULL, 1),
(6869298, 1033982, 28742, '<td valign="top">As I look off in the distance, I see an end to your weariness. ;-) Great job, monkey! 9</td>', 'As I look off in the distance, I see an end to your weariness. ;-) Great job, monkey! 9', '2012-09-25 18:21:32.000000', NULL, 1),
(6869301, 1034283, 28742, '<td valign="top">You never get used to scenes like this. ;-) GREAT job. Bumping up a point. ...meh, two points.</td>', 'You never get used to scenes like this. ;-) GREAT job. Bumping up a point. ...meh, two points.', '2012-09-25 18:23:04.000000', NULL, 1),
(6869302, 1033832, 28742, '<td valign="top">Creative and quite appeeling, actually. :)</td>', 'Creative and quite appeeling, actually. :)', '2012-09-25 18:23:40.000000', NULL, 1),
(6869368, 1033928, 100831, '<td valign="top">go ahead do it. what an experience.</td>', 'go ahead do it. what an experience.', '2012-09-25 20:36:03.000000', NULL, 1),
(6869369, 1033551, 100831, '<td valign="top">okay, go. quicker.</td>', 'okay, go. quicker.', '2012-09-25 20:37:26.000000', NULL, 1),
(6869384, 1034263, 65234, '<td valign="top">My favorite of the sliced banana entries and one of my favorites overall in the challenge.  Really like the lighting; the individual slices are nicely shiny and detailed but nothing is blown out or harshly shadowed.  The peel is also rather artfully composed.</td>', 'My favorite of the sliced banana entries and one of my favorites overall in the challenge.  Really like the lighting; the individual slices are nicely shiny and detailed but nothing is blown out or harshly shadowed.  The peel is also rather artfully composed.', '2012-09-25 21:15:00.000000', NULL, 1),
(6869385, 1033667, 65234, '<td valign="top">Very cute!  Quite a lot of effort went into decorating that banana :-)  The matching bee is a nice addition.  Looks like a Carpenter Bee, so I am fancifully imagining this one specialized in hole punching LOL.</td>', 'Very cute!  Quite a lot of effort went into decorating that banana :-)  The matching bee is a nice addition.  Looks like a Carpenter Bee, so I am fancifully imagining this one specialized in hole punching LOL.', '2012-09-25 21:17:18.000000', NULL, 1),
(6869386, 1033848, 109363, '<td valign="top">love anything with miniatures... and nice lighting</td>', 'love anything with miniatures... and nice lighting', '2012-09-25 21:18:34.000000', NULL, 1),
(6869388, 1033848, 65234, '<td valign="top">Awfully adorable, and I am not predisposed to like toy images, for some reason.  But this one is very well done and quite amusing.  A little heavily shadowed in places but not so much that it detracts a lot.</td>', 'Awfully adorable, and I am not predisposed to like toy images, for some reason.  But this one is very well done and quite amusing.  A little heavily shadowed in places but not so much that it detracts a lot.', '2012-09-25 21:18:44.000000', NULL, 1),
(6869389, 1034202, 109363, '<td valign="top">lovingly disturbing</td>', 'lovingly disturbing', '2012-09-25 21:18:49.000000', NULL, 1),
(6869391, 1034264, 109363, '<td valign="top">simplistic beauty</td>', 'simplistic beauty', '2012-09-25 21:19:02.000000', NULL, 1),
(6869392, 1034283, 109363, '<td valign="top">like the processing</td>', 'like the processing', '2012-09-25 21:19:14.000000', NULL, 1),
(6869393, 1034269, 109363, '<td valign="top">ha!  nice product placement</td>', 'ha!  nice product placement', '2012-09-25 21:19:40.000000', NULL, 1),
(6869394, 1034248, 65234, '<td valign="top">Sorta'' reminds me of a rocket ship.  Possibly ejecting unnecessary bits ;-)  Overall this is nicely lit, though I am seeing a bit of banding in the background.</td>', 'Sorta'' reminds me of a rocket ship.  Possibly ejecting unnecessary bits ;-)  Overall this is nicely lit, though I am seeing a bit of banding in the background.', '2012-09-25 21:20:00.000000', NULL, 1),
(6869395, 1033928, 109363, '<td valign="top">beautiful use of blur and focus, sat/desat</td>', 'beautiful use of blur and focus, sat/desat', '2012-09-25 21:20:26.000000', NULL, 1),
(6869396, 1034253, 109363, '<td valign="top">nice still life.  would definitely work on the kitchen wall</td>', 'nice still life.  would definitely work on the kitchen wall', '2012-09-25 21:21:00.000000', NULL, 1),
(6869397, 1034254, 65234, '<td valign="top">I sure hope that Hummer got rewarded for posing!  Definitely an unusual way to lure one in, and she''s beautifully detailed.</td>', 'I sure hope that Hummer got rewarded for posing!  Definitely an unusual way to lure one in, and she''s beautifully detailed.', '2012-09-25 21:21:13.000000', NULL, 1),
(6869399, 1033918, 109363, '<td valign="top">a little too blurry</td>', 'a little too blurry', '2012-09-25 21:21:37.000000', NULL, 1),
(6869400, 1034228, 109363, '<td valign="top">nothing here to really grab my interest</td>', 'nothing here to really grab my interest', '2012-09-25 21:21:58.000000', NULL, 1),
(6869401, 1034134, 109363, '<td valign="top">might have better in B&amp;W, and with a little less reflection/brightness in the watch face</td>', 'might have better in B&W, and with a little less reflection/brightness in the watch face', '2012-09-25 21:22:40.000000', NULL, 1),
(6869402, 1034200, 109363, '<td valign="top">i''m sure you did this within the rules, right? ;-)</td>', 'i''m sure you did this within the rules, right? ;-)', '2012-09-25 21:23:16.000000', NULL, 1),
(6869403, 1033667, 109363, '<td valign="top">nice ink!</td>', 'nice ink!', '2012-09-25 21:23:37.000000', NULL, 1),
(6869404, 1033832, 65234, '<td valign="top">Had to give you a bonus point for the title LOL.  The bananas aren''t as gracefully artsy as the rest of the arrangement but I still think it''s pretty funny that you used them this way :-)</td>', 'Had to give you a bonus point for the title LOL.  The bananas aren''t as gracefully artsy as the rest of the arrangement but I still think it''s pretty funny that you used them this way :-)', '2012-09-25 21:23:53.000000', NULL, 1),
(6869405, 1034206, 109363, '<td valign="top">nice lighting... one of the better photos of JUST bananas</td>', 'nice lighting... one of the better photos of JUST bananas', '2012-09-25 21:24:22.000000', NULL, 1),
(6869406, 1034200, 65234, '<td valign="top">Ooh, tricksy!  Well done.</td>', 'Ooh, tricksy!  Well done.', '2012-09-25 21:24:30.000000', NULL, 1),
(6869407, 1033812, 65234, '<td valign="top">You''ve made a banana seem mysterious.  I''m impressed.</td>', 'You''ve made a banana seem mysterious.  I''m impressed.', '2012-09-25 21:24:56.000000', NULL, 1),
(6869408, 1034264, 65234, '<td valign="top">Simple, but elegant in composition.</td>', 'Simple, but elegant in composition.', '2012-09-25 21:25:17.000000', NULL, 1),
(6869409, 1034137, 109363, '<td valign="top">well, there was a "banana hammock" in the previous challenge...</td>', 'well, there was a "banana hammock" in the previous challenge...', '2012-09-25 21:26:04.000000', NULL, 1),
(6869410, 1034227, 65234, '<td valign="top">My dogs would have devoured the banana.  They love them!!  Clearly this is a wiser sort of dog.</td>', 'My dogs would have devoured the banana.  They love them!!  Clearly this is a wiser sort of dog.', '2012-09-25 21:26:14.000000', NULL, 1),
(6869411, 1034225, 65234, '<td valign="top">Clever!  Nicely lit, too.</td>', 'Clever!  Nicely lit, too.', '2012-09-25 21:26:30.000000', NULL, 1),
(6869413, 1034137, 65234, '<td valign="top">There''s a device for hanging a banana?!  That''s sort of disturbing.</td>', 'There''s a device for hanging a banana?!  That''s sort of disturbing.', '2012-09-25 21:27:14.000000', NULL, 1),
(6869414, 1034088, 65234, '<td valign="top">Nicely smoked.</td>', 'Nicely smoked.', '2012-09-25 21:27:23.000000', NULL, 1),
(6869415, 1034231, 109363, '<td valign="top">i think the black on the sides takes away from the image... might have put the banana in the bag as it was on its side, then fill the frame with those great colors and the silhouette</td>', 'i think the black on the sides takes away from the image... might have put the banana in the bag as it was on its side, then fill the frame with those great colors and the silhouette', '2012-09-25 21:27:30.000000', NULL, 1),
(6869416, 1034173, 65234, '<td valign="top">You just never know what will inspire an artist!</td>', 'You just never know what will inspire an artist!', '2012-09-25 21:28:02.000000', NULL, 1),
(6869417, 1034284, 65234, '<td valign="top">LOL!  Well played.</td>', 'LOL!  Well played.', '2012-09-25 21:28:17.000000', NULL, 1),
(6869418, 1034271, 65234, '<td valign="top">That is the prettiest old banana peel I''ve ever seen!</td>', 'That is the prettiest old banana peel I''ve ever seen!', '2012-09-25 21:28:42.000000', NULL, 1),
(6869420, 1034285, 65234, '<td valign="top">Who knew they could be such potent weapons?</td>', 'Who knew they could be such potent weapons?', '2012-09-25 21:29:02.000000', NULL, 1),
(6869421, 1034250, 65234, '<td valign="top">It looks sort of sad lying on its side like that.  The softness adds a bit more pathos to the scene.</td>', 'It looks sort of sad lying on its side like that.  The softness adds a bit more pathos to the scene.', '2012-09-25 21:29:44.000000', NULL, 1),
(6869425, 1033714, 65234, '<td valign="top">Well done!  Not quite as interesting to me compositionally as some of the other splits (I think I might prefer a background with no horizon), but still very cool.</td>', 'Well done!  Not quite as interesting to me compositionally as some of the other splits (I think I might prefer a background with no horizon), but still very cool.', '2012-09-25 21:32:51.000000', NULL, 1),
