(6869427, 1034206, 65234, '<td valign="top">Simple, and the harsh light suits the subjects being past their prime.</td>', 'Simple, and the harsh light suits the subjects being past their prime.', '2012-09-25 21:33:27.000000', NULL, 1),
(6869428, 1033928, 113278, '<td valign="top">Perfect<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1028934" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/110000-114999/113278/120/Copyrighted_Image_Reuse_Prohibited_1028934.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/110000-114999/113278/120/Copyrighted_Image_Reuse_Prohibited_1028934.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/110000-114999/113278/120/Copyrighted_Image_Reuse_Prohibited_1028934.jpg"/></a></td>', 'Perfect', '2012-09-25 21:33:58.000000', NULL, 1),
(6869431, 1034228, 65234, '<td valign="top">Like the concept, but not blown away by the result.  Light/shadow is rather harsh and the background is too complicated for such a simple story, IMO.  I''d use a plain white background and then make my life complicated by trying to photograph at least one banana in the act of falling ;-)</td>', 'Like the concept, but not blown away by the result.  Light/shadow is rather harsh and the background is too complicated for such a simple story, IMO.  I''d use a plain white background and then make my life complicated by trying to photograph at least one banana in the act of falling ;-)', '2012-09-25 21:40:03.000000', NULL, 1),
(6869433, 1034134, 65234, '<td valign="top">Maturing because time is passing?  Kind of guessing here.  The glare on the watch is pretty harsh.</td>', 'Maturing because time is passing?  Kind of guessing here.  The glare on the watch is pretty harsh.', '2012-09-25 21:41:26.000000', NULL, 1),
(6869434, 1034253, 124815, '<td valign="top">Soft, well said; a touch too muddy, esp. the wall behind the bananas where it became dirty-greenish. Painterly.</td>', 'Soft, well said; a touch too muddy, esp. the wall behind the bananas where it became dirty-greenish. Painterly.', '2012-09-25 21:48:31.000000', NULL, 1),
(6869437, 1034279, 124815, '<td valign="top">A nice idea. And good execution.</td>', 'A nice idea. And good execution.', '2012-09-25 21:58:28.000000', NULL, 1),
(6869439, 1033928, 124815, '<td valign="top">Glad to see a scene, a story.</td>', 'Glad to see a scene, a story.', '2012-09-25 22:02:00.000000', NULL, 1),
